"""Build the review workbench. No source aircraft or original UV is modified."""
from pathlib import Path
import base64, hashlib, json, os, re, subprocess, urllib.request
from PIL import Image

ROOT = Path(__file__).resolve().parents[2]
HERE = Path(__file__).resolve().parent
RES = Path(os.environ.get('B24_RESOURCES', '/tmp/b24resources'))
RES.mkdir(parents=True, exist_ok=True)
VENDOR = RES / 'vendor' / 'three'
PHOTOS = RES / 'photos'
PHOTOS.mkdir(exist_ok=True)
if not VENDOR.exists():
    VENDOR.parent.mkdir(exist_ok=True)
    subprocess.run(['npm','pack','three@0.169.0','--silent'],cwd=VENDOR.parent,check=True)
    subprocess.run(['tar','-xzf','three-0.169.0.tgz'],cwd=VENDOR.parent,check=True)
    (VENDOR.parent/'package').rename(VENDOR)

sources = {
    'port': ('https://asisbiz.com/il2/B-24/308BG/images/42-73257-B-24J-Liberator-14AF-308BG374BS-no-487-named-80-Days-nose-art-left-side-China-01.jpg','07439c42eac526d5a209a6bf767853302089099eda4df11128a0e8b56a6a81fa'),
    'starboard': ('https://dainthecbi.com/images/pitterle/80-days.jpg','4ffd9160fba0d00ffd47e4925bcddc55c4efde800e17e3b73afc26007b248c06'),
}
photos={}
for key,(url,sha) in sources.items():
    path=PHOTOS/(key+'.jpg')
    if not path.exists():
        req=urllib.request.Request(url,headers={'User-Agent':'Mozilla/5.0'})
        with urllib.request.urlopen(req,timeout=40) as response: path.write_bytes(response.read())
    raw=path.read_bytes()
    if hashlib.sha256(raw).hexdigest()!=sha: raise ValueError('Reference bytes changed: '+key)
    with Image.open(path) as im: w,h=im.size
    photos[key]={'url':url,'sha256':sha,'width':w,'height':h,'bytes':len(raw),'data':'data:image/jpeg;base64,'+base64.b64encode(raw).decode()}

engine=VENDOR/'build/three.module.min.js'
# Resolve relative module references into stable bare import keys. Import maps
# provide data URLs, so the standalone file needs no CDN for its first screen.
modules={}
def register(path,key):
    if key in modules:return
    text=path.read_text()
    modules[key]=''
    def fix(match):
        relative=match.group(1)
        target=(path.parent/relative).resolve()
        addon=target.relative_to((VENDOR/'examples/jsm').resolve()).as_posix()
        child='three/addons/'+addon
        register(target,child)
        return "from '"+child+"'"
    text=re.sub(r"from\s+['\"](\.[^'\"]+)['\"]",fix,text)
    text=re.sub(r'//# sourceMappingURL=.*','',text)
    modules[key]='data:text/javascript;base64,'+base64.b64encode(text.encode()).decode()
modules['three']='data:text/javascript;base64,'+base64.b64encode(engine.read_bytes()).decode()
for addon in ['controls/OrbitControls.js','loaders/GLTFLoader.js','environments/RoomEnvironment.js']:
    register(VENDOR/'examples/jsm'/addon,'three/addons/'+addon)
math=ROOT/'experiments/80-days-material-r1/material-channels.mjs'
modules['material-math']='data:text/javascript;base64,'+base64.b64encode(math.read_bytes()).decode()
app=(HERE/'app.mjs').read_text()
# Unary negation must be outside the exponent expression in ECMAScript.
app=app.replace('Math.exp(-((u-.83)/.17)**2-((v-.41)/.3)**2)', 'Math.exp(-(((u-.83)/.17)**2)-(((v-.41)/.3)**2))')
(HERE/'app.syntax-check.mjs').write_text(app)
subprocess.run(['node','--check',str(HERE/'app.syntax-check.mjs')],check=True)
(HERE/'app.syntax-check.mjs').unlink()
model_path=ROOT/'public/assets/model/b-24_liberator.glb'
model=model_path.read_bytes()
model_sha='541c3dcfb98ab590cdb1bc90d6ddcdfe80bce2a4b937f3bccefab0c7efe8be0d'
assert len(model)==23085972 and hashlib.sha256(model).hexdigest()==model_sha
